(2005, 'Exodus 20:17', 'Exodus', 20, 17, '&nbsp;د خپل ګاونډى د کور خواهش مۀ کوئ، د هغۀ د ښځې، د هغۀ د نوکرانو، د هغۀ د څاروو، خرونو او د هغه يو شى لالچ هم مۀ کوئ کوم چې ستاسو د ګاونډى وى.“', NULL, '&nbsp;د خپل ګاونډى د کور خواهش مۀ کوئ، د هغۀ د ښځې، د هغۀ د نوکرانو، د هغۀ د څاروو، خرونو او د هغه يو شى لالچ هم مۀ کوئ کوم چې ستاسو د ګاونډى وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2006, 'Exodus 20:18', 'Exodus', 20, 18, '&nbsp;چې کله خلقو د تندرونو او د بيګل آواز واورېدو او برېښناګانې او د غرۀ لوګى يې وليدل، هغوئ د يرې نه ولړزېدل او لرې ودرېدل.', NULL, '&nbsp;چې کله خلقو د تندرونو او د بيګل آواز واورېدو او برېښناګانې او د غرۀ لوګى يې وليدل، هغوئ د يرې نه ولړزېدل او لرې ودرېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2007, 'Exodus 20:19', 'Exodus', 20, 19, '&nbsp;هغوئ موسىٰ ته ووئيل، ”کۀ تۀ زمونږ سره خبرې کوې نو مونږ به ورته غوږ ونيسو، خو کۀ خُدائ پاک زمونږ سره خبرې وکړى نو مونږ يريږو چې مړۀ به شو.“', NULL, '&nbsp;هغوئ موسىٰ ته ووئيل، ”کۀ تۀ زمونږ سره خبرې کوې نو مونږ به ورته غوږ ونيسو، خو کۀ خُدائ پاک زمونږ سره خبرې وکړى نو مونږ يريږو چې مړۀ به شو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2008, 'Exodus 20:20', 'Exodus', 20, 20, '&nbsp;موسىٰ ورته وفرمائيل، ”يرېږئ مه، خُدائ پاک خو صِرف دې له راغلے دے چې تاسو وآزمائى او خپله يره ستاسو په زړونو کښې واچوى چې تاسو ګناه نۀ کوئ.“', NULL, '&nbsp;موسىٰ ورته وفرمائيل، ”يرېږئ مه، خُدائ پاک خو صِرف دې له راغلے دے چې تاسو وآزمائى او خپله يره ستاسو په زړونو کښې واچوى چې تاسو ګناه نۀ کوئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2009, 'Exodus 20:21', 'Exodus', 20, 21, '&nbsp;خو خلق هم هغه شان لرې ولاړ وُو او صِرف موسىٰ هغه تکې تورې تيارې له نزدې ورَغلو چرته چې خُدائ پاک وو.', NULL, '&nbsp;خو خلق هم هغه شان لرې ولاړ وُو او صِرف موسىٰ هغه تکې تورې تيارې له نزدې ورَغلو چرته چې خُدائ پاک وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2010, 'Exodus 20:22', 'Exodus', 20, 22, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې، ”بنى اِسرائيلو ته ووائى، تاسو وليدل چې ما مالِک خُدائ ستاسو سره د آسمان نه څنګه خبرې کړې دى.', NULL, '&nbsp;بيا مالِک خُدائ موسىٰ ته حُکم وکړو چې، ”بنى اِسرائيلو ته ووائى، تاسو وليدل چې ما مالِک خُدائ ستاسو سره د آسمان نه څنګه خبرې کړې دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
