(2012, 'Exodus 20:24', 'Exodus', 20, 24, '&nbsp;زما دپاره د خاورې نه يوه قربان‌ګاه جوړه کړئ او په دې باندې خپل ګډان، چېلى او غوَيان د پوره سوزېدونکې قربانو او د سلامتۍ د قربانو په توګه حلالوئ. د خپل عبادت دپاره کوم ځائ چې زۀ درته وښايم نو هغه ځائ ته به زۀ تاسو له درځم او برکت به درکوم.', NULL, '&nbsp;زما دپاره د خاورې نه يوه قربان‌ګاه جوړه کړئ او په دې باندې خپل ګډان، چېلى او غوَيان د پوره سوزېدونکې قربانو او د سلامتۍ د قربانو په توګه حلالوئ. د خپل عبادت دپاره کوم ځائ چې زۀ درته وښايم نو هغه ځائ ته به زۀ تاسو له درځم او برکت به درکوم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2013, 'Exodus 20:25', 'Exodus', 20, 25, '&nbsp;کۀ تاسو زما دپاره د کاڼو نه يوه قربان‌ګاه جوړَوئ، نو هغه د تراشلے شوى کاڼو نه مۀ جوړَوئ، ځکه چې کله تاسو په هغه کاڼو آوزار لګوئ، نو هغه به ناپاکه کړئ.', NULL, '&nbsp;کۀ تاسو زما دپاره د کاڼو نه يوه قربان‌ګاه جوړَوئ، نو هغه د تراشلے شوى کاڼو نه مۀ جوړَوئ، ځکه چې کله تاسو په هغه کاڼو آوزار لګوئ، نو هغه به ناپاکه کړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2014, 'Exodus 20:26', 'Exodus', 20, 26, '&nbsp;زما دپاره داسې قربان‌ګاه مۀ جوړَوئ چې تاسو بره په پوړو ورخېژئ، ګنې ستاسو د سَتر اندامونه به بربنډ شى.“', NULL, '&nbsp;زما دپاره داسې قربان‌ګاه مۀ جوړَوئ چې تاسو بره په پوړو ورخېژئ، ګنې ستاسو د سَتر اندامونه به بربنډ شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2015, 'Exodus 21:1', 'Exodus', 21, 1, '&nbsp;”د بنى اِسرائيلو دپاره دا قانون مقرر کړه چې،', NULL, '&nbsp;”د بنى اِسرائيلو دپاره دا قانون مقرر کړه چې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2016, 'Exodus 21:2', 'Exodus', 21, 2, '&nbsp;کۀ تاسو يو عبرانے غلام واخلئ، هغه به شپږ کاله ستاسو خِدمت کوى. او په اوؤم کال به بغېر د څۀ څيز درکولو نه آزاد شى.', NULL, '&nbsp;کۀ تاسو يو عبرانے غلام واخلئ، هغه به شپږ کاله ستاسو خِدمت کوى. او په اوؤم کال به بغېر د څۀ څيز درکولو نه آزاد شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2017, 'Exodus 21:3', 'Exodus', 21, 3, '&nbsp;چې کله هغه د وادۀ نه مخکښې ستاسو غلام شوے وى، نو د آزادېدو په وخت به د ځان سره ښځه نۀ بوځى، خو چې کله هغه ستاسو غلام کېدلو او وادۀ يې کړے وو، نو هغه خپله ښځه د ځان سره بوتلے شى.', NULL, '&nbsp;چې کله هغه د وادۀ نه مخکښې ستاسو غلام شوے وى، نو د آزادېدو په وخت به د ځان سره ښځه نۀ بوځى، خو چې کله هغه ستاسو غلام کېدلو او وادۀ يې کړے وو، نو هغه خپله ښځه د ځان سره بوتلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2018, 'Exodus 21:4', 'Exodus', 21, 4, '&nbsp;کۀ مالِک ورله وادۀ وکړى او د هغۀ زامن يا لوڼه پېدا شى، نو هغه ښځه او د هغۀ بچى به د مالِک وى او هغه سړے چې آزاد کړے شى نو هغه يواځې تلے شى.', NULL, '&nbsp;کۀ مالِک ورله وادۀ وکړى او د هغۀ زامن يا لوڼه پېدا شى، نو هغه ښځه او د هغۀ بچى به د مالِک وى او هغه سړے چې آزاد کړے شى نو هغه يواځې تلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2019, 'Exodus 21:5', 'Exodus', 21, 5, '&nbsp;خو کۀ غلام صفا ووائى چې زۀ د خپل مالِک سره، خپلې ښځې او خپلو بچو سره مينه لرم او آزادېدل نۀ غواړم،', NULL, '&nbsp;خو کۀ غلام صفا ووائى چې زۀ د خپل مالِک سره، خپلې ښځې او خپلو بچو سره مينه لرم او آزادېدل نۀ غواړم،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
