(2021, 'Exodus 21:7', 'Exodus', 21, 7, '&nbsp;کۀ يو سړے خپله لور د وينځې په توګه خرڅه کړى، نو هغه به د نرانو نوکرانو په شان نۀ شى آزادولے.', NULL, '&nbsp;کۀ يو سړے خپله لور د وينځې په توګه خرڅه کړى، نو هغه به د نرانو نوکرانو په شان نۀ شى آزادولے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2022, 'Exodus 21:8', 'Exodus', 21, 8, '&nbsp;کۀ هغه په يو داسې کس خرڅه کړے شى چې هغه يې د ښځې کولو اراده لرى، خو د هغۀ دا خوښه نۀ وى، نو خپل پلار به دا واپس اخلى، د هغې مالِک دا په پردو خلقو نۀ شى خرڅولے، ځکه چې هغۀ د دې سره ټګى کړې ده.', NULL, '&nbsp;کۀ هغه په يو داسې کس خرڅه کړے شى چې هغه يې د ښځې کولو اراده لرى، خو د هغۀ دا خوښه نۀ وى، نو خپل پلار به دا واپس اخلى، د هغې مالِک دا په پردو خلقو نۀ شى خرڅولے، ځکه چې هغۀ د دې سره ټګى کړې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2023, 'Exodus 21:9', 'Exodus', 21, 9, '&nbsp;کۀ يو سړے د خپل زوئ دپاره وينځه واخلى، نو هغه به د هغې سره د لور په شان سلوک کوى.', NULL, '&nbsp;کۀ يو سړے د خپل زوئ دپاره وينځه واخلى، نو هغه به د هغې سره د لور په شان سلوک کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
