(2034, 'Exodus 21:22', 'Exodus', 21, 22, '&nbsp;کۀ څۀ کسان په جګړه وى او يوه اُميدواره ښځه ووهى او چې د هغې اولاد وغورزيږى، خو بل ځائ يې زخمى نۀ وى، نو چا چې هغه وهلى وى هغه به دومره جرمانه کيږى چې څومره جرمانه د هغې ښځې خاوند غواړى او چې قاضيان ووائى چې دا جرمانه صحيح ده.', NULL, '&nbsp;کۀ څۀ کسان په جګړه وى او يوه اُميدواره ښځه ووهى او چې د هغې اولاد وغورزيږى، خو بل ځائ يې زخمى نۀ وى، نو چا چې هغه وهلى وى هغه به دومره جرمانه کيږى چې څومره جرمانه د هغې ښځې خاوند غواړى او چې قاضيان ووائى چې دا جرمانه صحيح ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
