(2055, 'Exodus 22:10', 'Exodus', 22, 10, '&nbsp;کۀ يو کس بل کس له خپل خر، غوا، ګډه يا بل څاروے امانت ورکړى او هغه مړ يا زخمى شى يا په داسې وخت کښې وتښتولے شى چې هيڅ څوک يې هم ونۀ وينى،', NULL, '&nbsp;کۀ يو کس بل کس له خپل خر، غوا، ګډه يا بل څاروے امانت ورکړى او هغه مړ يا زخمى شى يا په داسې وخت کښې وتښتولے شى چې هيڅ څوک يې هم ونۀ وينى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2056, 'Exodus 22:11', 'Exodus', 22, 11, '&nbsp;نو هغه کس به ورته د مالِک خُدائ په نوم قسم کوى چې د هغه بل کس ځناور يې نۀ دے پټ کړے. کۀ هغه ځناور چا نۀ وى پټ کړے، نو هغه مالِک دې دا قسم ومنى او تاوان ورکولو ته ضرورت نشته،', NULL, '&nbsp;نو هغه کس به ورته د مالِک خُدائ په نوم قسم کوى چې د هغه بل کس ځناور يې نۀ دے پټ کړے. کۀ هغه ځناور چا نۀ وى پټ کړے، نو هغه مالِک دې دا قسم ومنى او تاوان ورکولو ته ضرورت نشته،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2057, 'Exodus 22:12', 'Exodus', 22, 12, '&nbsp;خو کۀ ځناور چا پټ کړے وى، نو هغه کس به خامخا مالِک ته د هغې تاوان ورکوى.', NULL, '&nbsp;خو کۀ ځناور چا پټ کړے وى، نو هغه کس به خامخا مالِک ته د هغې تاوان ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
