(2137, 'Exodus 25:12', 'Exodus', 25, 12, '&nbsp;د وړلو دپاره ورله د سرو زرو څلور ګول کَړۍ جوړې کړه او دا ورله په څلورو پښو پورې ولګوه، چې دوه کَړۍ يو خوا وى او دوه بل خوا وى.', NULL, '&nbsp;د وړلو دپاره ورله د سرو زرو څلور ګول کَړۍ جوړې کړه او دا ورله په څلورو پښو پورې ولګوه، چې دوه کَړۍ يو خوا وى او دوه بل خوا وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2138, 'Exodus 25:13', 'Exodus', 25, 13, '&nbsp;د وړلو دپاره ورله د کيکر لرګى نه بازوګان جوړ کړه او د سرو زرو پترى ورباندې وخېژوه', NULL, '&nbsp;د وړلو دپاره ورله د کيکر لرګى نه بازوګان جوړ کړه او د سرو زرو پترى ورباندې وخېژوه', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2139, 'Exodus 25:14', 'Exodus', 25, 14, '&nbsp;او دا بازوګان د صندوق د وړولو دپاره په کړو کښې دواړو طرفونو ته وردننه کړه.', NULL, '&nbsp;او دا بازوګان د صندوق د وړولو دپاره په کړو کښې دواړو طرفونو ته وردننه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2140, 'Exodus 25:15', 'Exodus', 25, 15, '&nbsp;هغه بازوګان به په هغه کړو کښې پرېږدئ او وباسئ به يې ترېنه نه.', NULL, '&nbsp;هغه بازوګان به په هغه کړو کښې پرېږدئ او وباسئ به يې ترېنه نه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
