(2253, 'Exodus 28:32', 'Exodus', 28, 32, '&nbsp;په هغې کښې به د سر دپاره يو سورے وى، چې غاړه يې مضبوطه ګنډلے شوى وى چې ونۀ شليږى.', NULL, '&nbsp;په هغې کښې به د سر دپاره يو سورے وى، چې غاړه يې مضبوطه ګنډلے شوى وى چې ونۀ شليږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2254, 'Exodus 28:35', 'Exodus', 28, 35, '&nbsp;چې کله هارون د اِمام په توګه خِدمت کوى نو هغه به دا چُوغه اغوندى. چې کله هغه زما په حضور کښې مقدس ځائ ته ننوځى يا ترې نه وځى، نو د ټلو آواز به اورېدلے شى او هغه به نۀ مړ کيږى.', NULL, '&nbsp;چې کله هارون د اِمام په توګه خِدمت کوى نو هغه به دا چُوغه اغوندى. چې کله هغه زما په حضور کښې مقدس ځائ ته ننوځى يا ترې نه وځى، نو د ټلو آواز به اورېدلے شى او هغه به نۀ مړ کيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2255, 'Exodus 28:36', 'Exodus', 28, 36, '&nbsp;د سوچه سرو زرو نه يوه نښه جوړه کړه او په هغې باندې وليکه، ”مالِک خُدائ ته وقف شوے.“', NULL, '&nbsp;د سوچه سرو زرو نه يوه نښه جوړه کړه او په هغې باندې وليکه، ”مالِک خُدائ ته وقف شوے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
