(2257, 'Exodus 28:38', 'Exodus', 28, 38, '&nbsp;هارون به دا په خپل تندى باندې وتړى، نو زۀ مالِک خُدائ به هغه نذرانې قبلوم چې بنى اِسرائيل يې ما ته وقف کوى، کۀ خلق د دې په پېش کولو کښې څۀ غلطى هم کوى.', NULL, '&nbsp;هارون به دا په خپل تندى باندې وتړى، نو زۀ مالِک خُدائ به هغه نذرانې قبلوم چې بنى اِسرائيل يې ما ته وقف کوى، کۀ خلق د دې په پېش کولو کښې څۀ غلطى هم کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2258, 'Exodus 28:39', 'Exodus', 28, 39, '&nbsp;د هارون دپاره د کتان نه يو قميص جوړ کړه او د کتان نه ورله پټکے جوړ کړه او يو کمربند هم جوړ کړه چې ګُلکارى ورباندې شوې وى.', NULL, '&nbsp;د هارون دپاره د کتان نه يو قميص جوړ کړه او د کتان نه ورله پټکے جوړ کړه او يو کمربند هم جوړ کړه چې ګُلکارى ورباندې شوې وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
