(2283, 'Exodus 29:21', 'Exodus', 29, 21, '&nbsp;څۀ وينه واخله چې کومه په قربان‌ګاه باندې پرته وى او څۀ د غوړولو تېل واخله او دا د هارون او د هغۀ په جامو او د هغۀ زامنو او د هغوئ په جامو باندې وشينده. نو هغه، د هغۀ زامن او د هغوئ جامې به ما ته وقف شى.', NULL, '&nbsp;څۀ وينه واخله چې کومه په قربان‌ګاه باندې پرته وى او څۀ د غوړولو تېل واخله او دا د هارون او د هغۀ په جامو او د هغۀ زامنو او د هغوئ په جامو باندې وشينده. نو هغه، د هغۀ زامن او د هغوئ جامې به ما ته وقف شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
