(2287, 'Exodus 29:25', 'Exodus', 29, 25, '&nbsp;بيا دا د هغوئ د لاسونو نه واخله او دا په قربان‌ګاه باندې د سوزېدونکې نذرانې سره وسوزوه. د دې خوشبو هم په مالِک خُدائ باندې ښۀ لګى.', NULL, '&nbsp;بيا دا د هغوئ د لاسونو نه واخله او دا په قربان‌ګاه باندې د سوزېدونکې نذرانې سره وسوزوه. د دې خوشبو هم په مالِک خُدائ باندې ښۀ لګى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
