(2360, 'Exodus 31:14', 'Exodus', 31, 14, '&nbsp;تاسو خامخا د سبت ورځ منئ، ځکه چې دا ستاسو دپاره مقدسه ده. چې څوک هم دا نۀ منى او په هغه ورځ کار کوى، نو هغه دې ووژلے شى. او څوک چې په هغه ورځ باندې کار کوى نو هغه به د بنى اِسرائيلو نه نۀ شى ګڼلے.', NULL, '&nbsp;تاسو خامخا د سبت ورځ منئ، ځکه چې دا ستاسو دپاره مقدسه ده. چې څوک هم دا نۀ منى او په هغه ورځ کار کوى، نو هغه دې ووژلے شى. او څوک چې په هغه ورځ باندې کار کوى نو هغه به د بنى اِسرائيلو نه نۀ شى ګڼلے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
