(2363, 'Exodus 31:17', 'Exodus', 31, 17, '&nbsp;دا به همېشه دپاره زما او د بنى اِسرائيلو په مينځ کښې يوه نښه وى، ځکه چې ما مالِک خُدائ په شپږ ورځو کښې آسمان او زمکه جوړ کړل او په اوومه ورځ ما کار بس کړو او څۀ مې ونۀ کړل.“', NULL, '&nbsp;دا به همېشه دپاره زما او د بنى اِسرائيلو په مينځ کښې يوه نښه وى، ځکه چې ما مالِک خُدائ په شپږ ورځو کښې آسمان او زمکه جوړ کړل او په اوومه ورځ ما کار بس کړو او څۀ مې ونۀ کړل.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2364, 'Exodus 31:18', 'Exodus', 31, 18, '&nbsp;چې کله خُدائ پاک د سينا په غرۀ باندې د موسىٰ سره خبرې خلاصې کړې، نو هغۀ له يې هغه د کاڼى دوه تختې ورکړې چې په کومو باندې خُدائ پاک په خپله حُکمونه ليکلى وُو.', NULL, '&nbsp;چې کله خُدائ پاک د سينا په غرۀ باندې د موسىٰ سره خبرې خلاصې کړې، نو هغۀ له يې هغه د کاڼى دوه تختې ورکړې چې په کومو باندې خُدائ پاک په خپله حُکمونه ليکلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2365, 'Exodus 32:1', 'Exodus', 32, 1, '&nbsp;چې کله خلقو وليدل چې موسىٰ د غرۀ نه راکوز نۀ شو او ډېر وخت يې هلته تېر کړو، نو هغوئ په هارون راغونډ شول او هغۀ ته يې ووئيل، ”مونږ نۀ پوهيږو چې په دې سړى، موسىٰ څۀ وشول، چې مونږ يې د مِصر نه راوويستلو، مونږ له معبودان جوړ کړه چې مونږ ته لارښودنه کوى.“', NULL, '&nbsp;چې کله خلقو وليدل چې موسىٰ د غرۀ نه راکوز نۀ شو او ډېر وخت يې هلته تېر کړو، نو هغوئ په هارون راغونډ شول او هغۀ ته يې ووئيل، ”مونږ نۀ پوهيږو چې په دې سړى، موسىٰ څۀ وشول، چې مونږ يې د مِصر نه راوويستلو، مونږ له معبودان جوړ کړه چې مونږ ته لارښودنه کوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
