(2370, 'Exodus 32:6', 'Exodus', 32, 6, '&nbsp;بل سحر وختى هغوئ څۀ ځناور راوستل چې د سوزېدونکې نذرانې په توګه يې قربان کړى او چې نور د خوړلو د سلامتۍ نذرانې په توګه پېش کړى. هغه خلق د خوړلو او څښلو دپاره کښېناستل او بيا هغوئ پاڅېدل، د مستۍ او عياشۍ سره ګډېدل.', NULL, '&nbsp;بل سحر وختى هغوئ څۀ ځناور راوستل چې د سوزېدونکې نذرانې په توګه يې قربان کړى او چې نور د خوړلو د سلامتۍ نذرانې په توګه پېش کړى. هغه خلق د خوړلو او څښلو دپاره کښېناستل او بيا هغوئ پاڅېدل، د مستۍ او عياشۍ سره ګډېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
