(2372, 'Exodus 32:8', 'Exodus', 32, 8, '&nbsp;چې په کومه لاره ما هغوئ له د عمل کولو حُکم ورکړے وو هغوئ زر د هغې نه بې‌لارې شوى دى، هغوئ د ويلې شوى سرو زرو نه سخے جوړ کړے دے، د هغۀ عبادت يې کړے دے او قربانۍ يې ورته پېش کړى دى. هغوئ وائى چې هغه يې خُدائ دے چا چې د مِصر د مُلک نه راويستلى دى.', NULL, '&nbsp;چې په کومه لاره ما هغوئ له د عمل کولو حُکم ورکړے وو هغوئ زر د هغې نه بې‌لارې شوى دى، هغوئ د ويلې شوى سرو زرو نه سخے جوړ کړے دے، د هغۀ عبادت يې کړے دے او قربانۍ يې ورته پېش کړى دى. هغوئ وائى چې هغه يې خُدائ دے چا چې د مِصر د مُلک نه راويستلى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
