(2483, 'Exodus 35:26', 'Exodus', 35, 26, '&nbsp;ټولو کسبګرو ښځو چې د هغوئ زړۀ غوښتل د چېلو د وړۍ نه جوړه کپړه يې هم راوړه.', NULL, '&nbsp;ټولو کسبګرو ښځو چې د هغوئ زړۀ غوښتل د چېلو د وړۍ نه جوړه کپړه يې هم راوړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2484, 'Exodus 35:27', 'Exodus', 35, 27, '&nbsp;مشرانو اونيکس کاڼى او نور قيمتى کاڼى راوړل چې په پېش بند او د سينې په جېب يې ولګوى.', NULL, '&nbsp;مشرانو اونيکس کاڼى او نور قيمتى کاڼى راوړل چې په پېش بند او د سينې په جېب يې ولګوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2485, 'Exodus 35:28', 'Exodus', 35, 28, '&nbsp;او مصالحې او د ډيوو دپاره تېل، د غوړولو تېل او د خوشبويۍ مصالحې يې هم راوړې.', NULL, '&nbsp;او مصالحې او د ډيوو دپاره تېل، د غوړولو تېل او د خوشبويۍ مصالحې يې هم راوړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
