(2487, 'Exodus 35:30', 'Exodus', 35, 30, '&nbsp;موسىٰ بنى اِسرائيلو ته وفرمائيل، ”مالِک خُدائ د يهوداه د قبيلې بضلى‌اېل غوره کړے دے، چې د اورى زوئ او د حُور نمسے دے.', NULL, '&nbsp;موسىٰ بنى اِسرائيلو ته وفرمائيل، ”مالِک خُدائ د يهوداه د قبيلې بضلى‌اېل غوره کړے دے، چې د اورى زوئ او د حُور نمسے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2488, 'Exodus 35:31', 'Exodus', 35, 31, '&nbsp;هغه خُدائ پاک د خپل روح نه ډک کړے دے او هغۀ له يې پوهه، هُنر او د هر قِسم هُنر په کار کښې قابليت ورکړے دے،', NULL, '&nbsp;هغه خُدائ پاک د خپل روح نه ډک کړے دے او هغۀ له يې پوهه، هُنر او د هر قِسم هُنر په کار کښې قابليت ورکړے دے،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
