(2490, 'Exodus 35:33', 'Exodus', 35, 33, '&nbsp;د قيمتى کاڼى پرې کولو او تيارولو، د لرګى کار کولو، او د هر قِسم د هُنر کار دپاره.', NULL, '&nbsp;د قيمتى کاڼى پرې کولو او تيارولو، د لرګى کار کولو، او د هر قِسم د هُنر کار دپاره.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2491, 'Exodus 35:34', 'Exodus', 35, 34, '&nbsp;مالِک خُدائ هغۀ له او د دان قبيلې، د اخيسمک زوئ اهلياب له هم دا قابليت ورکړے دے چې خپل د هُنر کارونه نورو ته وښائى.', NULL, '&nbsp;مالِک خُدائ هغۀ له او د دان قبيلې، د اخيسمک زوئ اهلياب له هم دا قابليت ورکړے دے چې خپل د هُنر کارونه نورو ته وښائى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2492, 'Exodus 35:35', 'Exodus', 35, 35, '&nbsp;هغۀ هغوئ له په هر قِسم کار کښې مهارت ورکړے دے چې هغوئ د زرګرانو، د ماهِرانو او د کتان، د آسمانى رنګ، کاسنى او د سور رنګ وړۍ، او د نورې کپړې د جوړونکى په توګه کار وکړى. هغوئ د هر قِسم کار مهارت لرونکى کاريګران او د نوؤ څيزونو جوړولو اُستاذان دى.', NULL, '&nbsp;هغۀ هغوئ له په هر قِسم کار کښې مهارت ورکړے دے چې هغوئ د زرګرانو، د ماهِرانو او د کتان، د آسمانى رنګ، کاسنى او د سور رنګ وړۍ، او د نورې کپړې د جوړونکى په توګه کار وکړى. هغوئ د هر قِسم کار مهارت لرونکى کاريګران او د نوؤ څيزونو جوړولو اُستاذان دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2493, 'Exodus 36:1', 'Exodus', 36, 1, '&nbsp;بضلى‌اېل، اهلياب او نورو ټولو ماهِرو کسانو له مالِک خُدائ مهارت او پوهه ورکړې ده چې هغوئ هغه هر څۀ د مالِک خُدائ د حُکم په مطابق جوړ کړى چې په مقدسه خېمه کښې يې ضرورت وى.“', NULL, '&nbsp;بضلى‌اېل، اهلياب او نورو ټولو ماهِرو کسانو له مالِک خُدائ مهارت او پوهه ورکړې ده چې هغوئ هغه هر څۀ د مالِک خُدائ د حُکم په مطابق جوړ کړى چې په مقدسه خېمه کښې يې ضرورت وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
(2494, 'Exodus 36:2', 'Exodus', 36, 2, '&nbsp;بيا موسىٰ بضلى‌اېل، اهلياب او نور ټول ماهِر کسان راوغوښتل چا له چې مالِک خُدائ قابليت ورکړے وو او چې د هغوئ زړۀ غوښتل چې کار وکړى او موسىٰ ورته وفرمائيل چې کار شروع کړئ.', NULL, '&nbsp;بيا موسىٰ بضلى‌اېل، اهلياب او نور ټول ماهِر کسان راوغوښتل چا له چې مالِک خُدائ قابليت ورکړے وو او چې د هغوئ زړۀ غوښتل چې کار وکړى او موسىٰ ورته وفرمائيل چې کار شروع کړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
