(2498, 'Exodus 36:6', 'Exodus', 36, 6, '&nbsp;نو موسىٰ اِعلان وکړو چې دا پېغام دې ټولو خېمو ته ورسولے شى چې نور به هيڅ څوک د مقدسې خېمې دپاره هيڅ هم نۀ راوړى، نو خلق د نورو نذرانو راوړلو نه منع کړے شول.', NULL, '&nbsp;نو موسىٰ اِعلان وکړو چې دا پېغام دې ټولو خېمو ته ورسولے شى چې نور به هيڅ څوک د مقدسې خېمې دپاره هيڅ هم نۀ راوړى، نو خلق د نورو نذرانو راوړلو نه منع کړے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432),
