(2500, 'Exodus 36:8', 'Exodus', 36, 8, '&nbsp;د ټولو نه تکړه کسانو د مالِک خُدائ د حضور خېمه جوړه کړه. هغوئ دا د مهينې لټې د لسو پړدو نه جوړه کړه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه جوړې وې او په دې باندې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړے شوے وو.', NULL, '&nbsp;د ټولو نه تکړه کسانو د مالِک خُدائ د حضور خېمه جوړه کړه. هغوئ دا د مهينې لټې د لسو پړدو نه جوړه کړه چې د آسمانى رنګ، کاسنى او د سور رنګ وړۍ نه جوړې وې او په دې باندې په ګُلکارۍ کښې د وزرو والا مخلوق جوړ کړے شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756432, 1761756432);